css:
*{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{font-family:var(--f-body);font-size:var(--fs-body);color:var(--c-text);background:var(--c-surface);line-height:1.65;-webkit-font-smoothing:antialiased;overflow-x:hidden}
h1,h2,h3,h4{font-family:var(--f-head);font-weight:var(--hw);line-height:var(--hlh);letter-spacing:var(--hls);text-transform:var(--hcase);color:var(--c-primary)}
h1{font-size:clamp(34px,6.2vw,var(--h1))}
h2{font-size:clamp(26px,3.8vw,var(--h2))}
h3{font-size:clamp(19px,2vw,var(--h3))}
a{color:inherit}
p{max-width:62ch}
.wrap{max-width:var(--w,1300px);margin:0 auto;padding:0 clamp(20px,4vw,40px)}
.sec{padding:var(--pad) 0}.sec.tight{padding:calc(var(--pad)*.6) 0}.sec.loose{padding:calc(var(--pad)*1.35) 0}
.alt{background:color-mix(in srgb,var(--c-primary) 6%,var(--c-surface))}
.dark{background:var(--c-primary);color:var(--on-primary)}
.dark h1,.dark h2,.dark h3,.dark h4{color:var(--on-primary)}
.band2{background:var(--c-secondary);color:var(--on-secondary)}
.band2 h1,.band2 h2,.band2 h3{color:var(--on-secondary)}
.muted{opacity:.72}
.eyebrow{font:var(--ew) 13px/1 var(--f-body);letter-spacing:.14em;text-transform:uppercase;color:var(--c-secondary);margin-bottom:18px;display:block}
.dark .eyebrow,.band2 .eyebrow{color:var(--on-primary);opacity:.8}
.lead{font-size:clamp(16px,1.6vw,19px);margin:20px 0 28px;opacity:.88}
.actions{display:flex;gap:12px;flex-wrap:wrap}
.btn{display:inline-flex;align-items:center;gap:8px;padding:.9em 1.7em;border-radius:var(--radius);font:var(--ew) 14px/1 var(--f-body);letter-spacing:.03em;background:var(--c-accent);color:var(--on-accent);border:2px solid var(--c-accent);text-decoration:none;cursor:pointer;transition:transform .2s,opacity .2s}
.btn:hover{transform:translateY(-2px);opacity:.92}
.btn.ghost{background:transparent;color:var(--c-primary);border-color:var(--c-primary)}
.dark .btn.ghost,.band2 .btn.ghost{color:var(--on-primary);border-color:var(--on-primary)}
.dark .btn:not(.ghost){background:var(--c-accent);border-color:var(--c-accent)}
.ph{width:100%;position:relative;border-radius:var(--radius);background:linear-gradient(135deg,color-mix(in srgb,var(--c-primary) 82%,#fff),color-mix(in srgb,var(--c-accent) 65%,var(--c-surface)));min-height:140px;overflow:hidden}
.ph::before{content:"";position:absolute;inset:0;background:repeating-linear-gradient(45deg,transparent 0 14px,rgba(255,255,255,.07) 14px 15px)}
.ph::after{content:attr(data-l);position:absolute;left:14px;bottom:12px;font:700 10px/1 var(--f-body);letter-spacing:.16em;text-transform:uppercase;color:#fff;opacity:.85}
.ph.soft{background:linear-gradient(135deg,color-mix(in srgb,var(--c-accent) 22%,var(--c-surface)),color-mix(in srgb,var(--c-primary) 28%,var(--c-surface)))}
.ph.soft::after{color:var(--c-primary)}
.grid2{display:grid;grid-template-columns:1.05fr .95fr;gap:clamp(28px,5vw,72px);align-items:center}
.rev .grid2>:first-child{order:2}

/* nav */
.nav{position:sticky;top:0;z-index:20;background:color-mix(in srgb,var(--c-surface) 92%,transparent);backdrop-filter:blur(8px);border-bottom:1px solid var(--c-border)}
.nav .wrap{display:flex;align-items:center;justify-content:space-between;height:68px;gap:20px}
.logo{font:var(--hw) 21px/1 var(--f-head);color:var(--c-primary);text-transform:var(--hcase);letter-spacing:var(--hls);text-decoration:none}
.nav ul{display:flex;gap:28px;list-style:none;font:500 14px var(--f-body)}
.nav ul a{text-decoration:none;opacity:.8}.nav ul a:hover{opacity:1;color:var(--c-accent)}
.nav .btn{padding:.65em 1.2em;font-size:13px}
.nav-center .wrap{flex-direction:column;height:auto;padding-top:18px;padding-bottom:14px;gap:12px}
.nav-center .logo{font-size:26px}
.nav-min{background:transparent;border:0;position:absolute;left:0;right:0}
.nav-min .navmenu{font:700 13px var(--f-body);letter-spacing:.14em;text-transform:uppercase}
.nav-dark{background:var(--c-primary);border-color:transparent}.nav-dark .logo,.nav-dark ul{color:var(--on-primary)}
@media(max-width:720px){.nav ul{display:none}.grid2{grid-template-columns:1fr}.rev .grid2>:first-child{order:0}}

/* heroes */
.hero{padding:clamp(48px,8vw,104px) 0}
.hero-center{text-align:center}.hero-center p{margin-left:auto;margin-right:auto}.hero-center .actions{justify-content:center}
.mock{margin:56px auto 0;max-width:920px;border-radius:calc(var(--radius) + 4px);border:1px solid var(--c-border);background:#fff;box-shadow:0 30px 60px -28px color-mix(in srgb,var(--c-primary) 45%,transparent);overflow:hidden;text-align:left}
.mock .bar{display:flex;gap:6px;padding:12px 14px;border-bottom:1px solid var(--c-border);background:color-mix(in srgb,var(--c-surface) 70%,#fff)}
.mock .bar i{width:10px;height:10px;border-radius:50%;background:var(--c-border)}
.mock .body{display:grid;grid-template-columns:150px 1fr;min-height:260px}
.mock .side{border-right:1px solid var(--c-border);padding:16px;display:grid;gap:10px;align-content:start}
.mock .side b{height:10px;border-radius:99px;background:var(--c-border)}
.mock .side b:first-child{background:var(--c-primary);width:70%}
.mock .main{padding:20px;display:grid;grid-template-columns:repeat(3,1fr);gap:14px;align-content:start}
.mock .main div{height:78px;border-radius:var(--radius);background:color-mix(in srgb,var(--c-primary) 9%,#fff)}
.mock .main div:first-child{grid-column:span 3;height:120px;background:linear-gradient(120deg,var(--c-primary),var(--c-accent))}
.hero-full{padding:clamp(120px,16vw,200px) 0 0}
.hero-full h1{font-size:clamp(52px,13vw,var(--h1big));line-height:.92;margin-bottom:28px}
.hero-full .ph{aspect-ratio:auto!important;border-radius:0;height:clamp(240px,40vw,460px);margin-top:48px}
.hero-diag{padding-bottom:clamp(70px,10vw,140px);clip-path:polygon(0 0,100% 0,100% 91%,0 100%)}
.frame{border:1px solid color-mix(in srgb,var(--on-primary) 35%,transparent);padding:clamp(60px,10vw,130px) 20px;text-align:center}
.frame p{margin-left:auto;margin-right:auto}.frame .actions{justify-content:center}
.frame h1{font-weight:var(--hw);font-style:italic}
.mag{display:grid;grid-template-columns:2fr 1fr;gap:40px;padding:36px 0 56px}
.mag .tag{font:700 11px var(--f-body);letter-spacing:.14em;text-transform:uppercase;color:var(--c-accent);display:block;margin-bottom:8px}
.mag h1{font-size:clamp(30px,4.6vw,var(--h1));margin:14px 0}
.mag .side{border-left:1px solid var(--c-border);padding-left:32px;display:grid;gap:22px;align-content:start}
.mag .side article{padding-bottom:22px;border-bottom:1px solid var(--c-border)}.mag .side article:last-child{border:0}
.mag .side h3{font-size:20px;margin-top:4px}
@media(max-width:820px){.mag{grid-template-columns:1fr}.mag .side{border:0;padding:0}}

/* generic parts */
.head{display:flex;justify-content:space-between;align-items:end;gap:24px;margin-bottom:clamp(28px,4vw,52px);flex-wrap:wrap}
.head h2{max-width:18ch}.head p{max-width:40ch;opacity:.8}
.logos{display:flex;gap:clamp(20px,5vw,64px);justify-content:center;flex-wrap:wrap;padding:30px 0;opacity:.55;font:700 15px var(--f-head);letter-spacing:.12em;text-transform:uppercase}
.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:30px}
.stats b{display:block;font:var(--hw) clamp(38px,5vw,60px)/1 var(--f-head);color:var(--stat);margin-bottom:6px}
.stats span{font-size:14px;opacity:.78}
.rows .row{display:grid;grid-template-columns:70px 1.1fr 1.6fr 30px;gap:24px;align-items:baseline;padding:26px 0;border-top:1px solid var(--c-border);transition:background .25s,padding .25s}
.rows .row:last-child{border-bottom:1px solid var(--c-border)}
.rows .row:hover{padding-left:14px;background:color-mix(in srgb,var(--c-primary) 5%,transparent)}
.rows .n{font:700 14px var(--f-body);color:var(--c-secondary)}
.rows .arr{color:var(--c-accent);font-weight:700}
@media(max-width:700px){.rows .row{grid-template-columns:40px 1fr;gap:6px 14px}.rows .row p{grid-column:2}.rows .arr{display:none}}
.card{background:color-mix(in srgb,var(--c-surface) 35%,#fff);border:1px solid var(--c-border);border-radius:var(--radius);padding:clamp(22px,3vw,34px)}
.card p{margin-top:8px;opacity:.82;font-size:15px}
.card .ico{width:42px;height:42px;border-radius:calc(var(--radius)*.7);background:color-mix(in srgb,var(--c-primary) 12%,#fff);margin-bottom:16px;display:grid;place-items:center;color:var(--c-primary);font:700 16px var(--f-head)}
.bento{display:grid;grid-template-columns:repeat(6,1fr);gap:16px}
.bento .card:nth-child(1){grid-column:span 4}.bento .card:nth-child(2){grid-column:span 2}.bento .card:nth-child(3){grid-column:span 2}.bento .card:nth-child(4){grid-column:span 4}
.bento .card.hl{background:var(--c-primary);color:var(--on-primary)}.bento .card.hl h3{color:var(--on-primary)}
@media(max-width:720px){.bento{grid-template-columns:1fr}.bento .card{grid-column:auto!important}}
.alt-row{display:grid;grid-template-columns:1fr 1fr;gap:clamp(28px,5vw,72px);align-items:center;margin-bottom:clamp(40px,6vw,84px)}
.alt-row:nth-child(even)>:first-child{order:2}
.alt-row .num{font:var(--hw) 14px var(--f-head);color:var(--c-secondary);letter-spacing:.14em}
.alt-row p{margin-top:12px;opacity:.85}
@media(max-width:720px){.alt-row{grid-template-columns:1fr}.alt-row:nth-child(even)>:first-child{order:0}}
.work{display:grid;grid-template-columns:repeat(12,1fr);gap:16px}
.work a{display:block;text-decoration:none;border:2px solid var(--c-primary);padding:12px;transition:background .25s,color .25s}
.work a:nth-child(1){grid-column:span 7}.work a:nth-child(2){grid-column:span 5;margin-top:56px}.work a:nth-child(3){grid-column:span 5}.work a:nth-child(4){grid-column:span 7}
.work a .ph{aspect-ratio:auto!important;height:clamp(180px,28vw,340px)}.work a h3{margin:14px 0 2px;font-size:22px;transition:color .25s}
.work a:hover{background:var(--c-primary);color:var(--on-primary)}.work a:hover h3{color:var(--on-primary)}
@media(max-width:720px){.work a{grid-column:span 12!important;margin-top:0!important}}
.products{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:26px 20px}
.products .ph{aspect-ratio:3/4}.products h3{font-size:17px;margin:14px 0 2px}.products .price{font:600 15px var(--f-body);color:var(--c-secondary)}
.products .tag{position:absolute;top:12px;left:12px;z-index:2;background:var(--c-accent);color:var(--on-accent);font:700 10px var(--f-body);letter-spacing:.1em;padding:5px 9px;border-radius:99px}
.articles{display:grid;grid-template-columns:1.4fr 1fr 1fr;gap:34px}
.articles article:first-child{grid-row:span 1}.articles h3{margin:12px 0 8px;font-size:clamp(20px,2.2vw,26px)}.articles article:first-child h3{font-size:clamp(24px,3vw,36px)}
.articles .meta{font:600 12px var(--f-body);letter-spacing:.1em;text-transform:uppercase;color:var(--c-secondary);margin-top:14px;display:block}
@media(max-width:820px){.articles{grid-template-columns:1fr}}
.menu{display:grid;grid-template-columns:1fr 1fr;gap:10px clamp(30px,6vw,90px);max-width:1000px;margin:0 auto}
.menu .it{padding:14px 0}.menu .l{display:flex;align-items:baseline;gap:10px}
.menu .l i{flex:1;border-bottom:1px dotted color-mix(in srgb,var(--on-primary) 45%,transparent)}
.menu .l b{font:600 22px var(--f-head);letter-spacing:.02em}.menu .l em{font:500 18px var(--f-head);font-style:normal;color:var(--c-accent)}
.menu p{font-size:15px;opacity:.7;margin-top:2px}
@media(max-width:720px){.menu{grid-template-columns:1fr}}
.dishes{display:grid;grid-template-columns:repeat(3,1fr);gap:26px}
.dishes>div:nth-child(2){transform:translateY(34px)}
.dishes .ph{aspect-ratio:4/3}.dishes .info{padding:16px 4px}.dishes h3{display:flex;justify-content:space-between;gap:10px;align-items:baseline}
.dishes h3 em{font:700 14px var(--f-body);font-style:normal;background:color-mix(in srgb,var(--c-accent) 14%,var(--c-surface));color:var(--c-accent);padding:4px 11px;border-radius:99px}
.dishes p{margin-top:6px;font-size:15px;opacity:.8}
@media(max-width:760px){.dishes{grid-template-columns:1fr}.dishes>div:nth-child(2){transform:none}}
.steps{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:28px}
.steps div{border-top:3px solid var(--c-accent);padding-top:18px}.steps b{font:var(--hw) 14px var(--f-head);letter-spacing:.12em;color:var(--c-secondary)}
.steps h3{margin:8px 0}.steps p{font-size:15px;opacity:.8}
.pricing{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;align-items:stretch}
.pricing .card{display:flex;flex-direction:column;gap:6px}.pricing .amt{font:var(--hw) 44px/1 var(--f-head);color:var(--c-primary);margin:10px 0}
.pricing .amt small{font:500 14px var(--f-body);opacity:.7}
.pricing ul{list-style:none;display:grid;gap:8px;margin:14px 0 22px;font-size:15px;flex:1}.pricing li::before{content:"\2713";color:var(--c-accent);margin-right:8px;font-weight:700}
.pricing .card.hl{background:var(--c-primary);color:var(--on-primary);transform:translateY(-12px)}
.pricing .card.hl li::before{color:var(--on-primary)}
.pricing .card.hl h3,.pricing .card.hl .amt{color:var(--on-primary)}
@media(max-width:820px){.pricing{grid-template-columns:1fr}.pricing .card.hl{transform:none}}
.quote{text-align:center;max-width:820px;margin:0 auto}
.quote blockquote{font:var(--hw) clamp(22px,3.2vw,36px)/1.35 var(--f-head);color:var(--c-primary);text-transform:none;letter-spacing:0}
.quote cite{display:block;margin-top:22px;font:600 14px var(--f-body);font-style:normal;letter-spacing:.08em;color:var(--c-secondary)}
.hours{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:30px}
.hours h4{font-size:14px;letter-spacing:.14em;text-transform:uppercase;opacity:.75;margin-bottom:8px;color:inherit}.hours p{font-size:17px}
.ctaband{display:flex;justify-content:space-between;align-items:center;gap:30px;flex-wrap:wrap}
.ctaband h2{max-width:20ch}.ctaband p{margin-top:10px;opacity:.85}
.giant{padding:clamp(70px,10vw,140px) 0 40px}
.giant a{display:block;font:var(--hw) clamp(32px,9.5vw,130px)/1 var(--f-head);text-transform:var(--hcase);color:var(--on-primary);text-decoration:none;word-break:break-all;transition:color .25s}
.giant a:hover{color:var(--c-accent)}
.foot{padding:48px 0 34px;font-size:14px}
.foot .cols{display:grid;grid-template-columns:1.6fr repeat(3,1fr);gap:30px;margin-bottom:34px}
.foot h4{font:700 12px var(--f-body);letter-spacing:.14em;text-transform:uppercase;margin-bottom:12px;opacity:.7;color:inherit}
.foot li{list-style:none;margin-bottom:7px;opacity:.85}.foot .copy{border-top:1px solid color-mix(in srgb,currentColor 20%,transparent);padding-top:20px;opacity:.65;font-size:13px}
@media(max-width:720px){.foot .cols{grid-template-columns:1fr 1fr}}
@media(prefers-reduced-motion:reduce){*{transition:none!important;scroll-behavior:auto!important}}

/* ===== multi-page additions ===== */
.wrap{max-width:var(--w,1300px)}
.nav .wrap{position:relative}
.nav ul a,.nav .dd a{text-decoration:none}
.nav li.more{position:relative}
.nav .dd{position:absolute;right:0;top:100%;padding:22px 26px;display:none;grid-template-columns:repeat(3,minmax(130px,1fr));gap:22px 34px;background:var(--c-surface);color:var(--c-text);border:1px solid var(--c-border);border-radius:var(--radius);box-shadow:0 24px 50px -18px rgba(0,0,0,.35);min-width:520px;z-index:30}
.nav li.more:hover .dd,.nav li.more:focus-within .dd{display:grid}
.nav .dd h4{font:700 11px var(--f-body);letter-spacing:.14em;text-transform:uppercase;margin-bottom:8px;opacity:.55;color:inherit}
.nav .dd a{display:block;padding:4px 0;font:500 14px var(--f-body);opacity:.85;color:inherit}.nav .dd a:hover{color:var(--c-accent);opacity:1}
.nav-center .dd{left:50%;right:auto;transform:translateX(-50%)}
.nav-dark li.more .dd{color:var(--c-text)}
.burger{display:none}.burger summary{list-style:none;cursor:pointer;font:700 13px var(--f-body);letter-spacing:.1em;text-transform:uppercase;padding:8px 12px;border:1px solid var(--c-border);border-radius:var(--radius)}
.burger summary::-webkit-details-marker{display:none}
.bmenu{position:absolute;left:0;right:0;top:100%;background:var(--c-surface);color:var(--c-text);padding:14px 20px 22px;display:grid;gap:2px;border-bottom:1px solid var(--c-border);max-height:70vh;overflow:auto}
.bmenu a{padding:8px 0;text-decoration:none;font-weight:600}
@media(max-width:820px){.nav ul{display:none}.nav .btn{display:none}.burger{display:block}.nav-center .wrap{flex-direction:row;justify-content:space-between}}
.minmenu summary{list-style:none;cursor:pointer;font:700 13px var(--f-body);letter-spacing:.14em;text-transform:uppercase;color:inherit;position:relative;z-index:61}
.minmenu summary::-webkit-details-marker{display:none}
.minov{position:fixed;inset:0;background:var(--c-primary);color:var(--on-primary);z-index:60;padding:110px clamp(24px,6vw,80px) 40px;display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:34px;align-content:start;overflow:auto}
.minmenu[open] summary{color:var(--on-primary)}
.minov h4{font:700 12px var(--f-body);letter-spacing:.14em;text-transform:uppercase;opacity:.6;margin-bottom:12px;color:var(--on-primary)}
.minov a{display:block;padding:4px 0;text-decoration:none;font:var(--hw) clamp(18px,2vw,26px)/1.25 var(--f-head);text-transform:var(--hcase);color:var(--on-primary)}.minov a:hover{color:var(--c-accent)}
.nav-min .logo,.nav-min{color:var(--on-primary)}.nav-min .logo{color:var(--on-primary)}
.foot a{color:inherit;text-decoration:none}.foot a:hover{text-decoration:underline}
.foot .cols{grid-template-columns:1.6fr repeat(auto-fit,minmax(110px,1fr))}
.foot .copy{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap}.foot .fl{display:flex;gap:18px;flex-wrap:wrap}
/* page head */
.pagehead{padding:clamp(48px,7vw,92px) 0 clamp(40px,5vw,64px)}
.nav-min+main .pagehead{padding-top:clamp(110px,14vw,170px)}
.pagehead h1{font-size:clamp(34px,5vw,calc(var(--h1)*.74));max-width:20ch}
.pagehead .lead{margin-top:16px;font-size:1.15em;opacity:.85;max-width:56ch}
.crumbs{display:flex;gap:8px;flex-wrap:wrap;font:600 13px var(--f-body);opacity:.7;margin-bottom:22px;align-items:center}
.crumbs a{text-decoration:none}.crumbs a:hover{text-decoration:underline}.crumbs span{opacity:.5}.crumbs b{font-weight:600;opacity:.8}
.muted{opacity:.7}
/* forms */
.form{display:grid;grid-template-columns:1fr 1fr;gap:16px}
.fld{display:grid;gap:6px}.fld.span2{grid-column:span 2}
.fld span{font:700 12px var(--f-body);letter-spacing:.08em;text-transform:uppercase;opacity:.75}
input,select,textarea{font:500 15px var(--f-body);color:var(--c-text);background:color-mix(in srgb,var(--c-surface) 40%,#fff);border:1px solid var(--c-border);border-radius:var(--radius);padding:.85em 1em;width:100%;outline:0}
input:focus,select:focus,textarea:focus{border-color:var(--c-accent);box-shadow:0 0 0 3px color-mix(in srgb,var(--c-accent) 20%,transparent)}
.inl{display:flex;gap:10px}.inl input{flex:1}
@media(max-width:600px){.form{grid-template-columns:1fr}.fld.span2{grid-column:auto}}
/* layout helpers */
.split{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(280px,1fr);gap:clamp(28px,5vw,64px);align-items:start}.split.w2{grid-template-columns:minmax(0,2.2fr) minmax(240px,1fr)}
@media(max-width:860px){.split,.split.w2{grid-template-columns:1fr}}
.side-card{border:1px solid var(--c-border);background:color-mix(in srgb,var(--c-surface) 35%,#fff);border-radius:var(--radius);padding:26px;position:sticky;top:96px}
.side-card h3{margin-bottom:12px}
.kv{list-style:none;margin:14px 0 20px}.kv li{display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid var(--c-border);gap:14px;font-size:15px}.kv li span{opacity:.7}.kv .tot{font-size:18px;border:0}
.price{font:var(--hw) 18px var(--f-head);color:var(--c-primary)}.price.big{font-size:34px;margin:6px 0 4px}
.prose h2{margin-top:6px}.prose p{margin-top:12px;max-width:68ch}.prose .two{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:30px}
